int binarySearch(const vector<int>& arr, int target) {
    int lo = 0, hi = arr.size() - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (arr[mid] == target) return mid;
        arr[mid] < target ? lo = mid + 1 : hi = mid - 1;
    }
    return -1;
}

