    void push_front(int val) {
        Node* n = new Node(val);
        n->next = head;
        head = n;
    }
    void push_back(int val) {
        Node* n = new Node(val);
        if (!head) { head = n; return; }
        Node* cur = head;
        while (cur->next) cur = cur->next;
        cur->next = n;
    }
