class Trie {
    struct Node {
        unordered_map<char, Node*> children;
        bool isEnd = false;
    };
    Node* root;
public:
    Trie() : root(new Node()) {}

    void insert(const string& word) {
        Node* cur = root;
        for (char c : word) {
            if (!cur->children.count(c)) cur->children[c] = new Node();
            cur = cur->children[c];
        }
        cur->isEnd = true;
    }

    bool search(const string& word) {
        Node* cur = root;
        for (char c : word) {
            if (!cur->children.count(c)) return false;
            cur = cur->children[c];
        }
        return cur->isEnd;
    }
};

int main() {
    Trie t;
    for (auto& w : {"apple", "app", "apply", "apt"})
        t.insert(w);
    cout << t.search("app") << "\n";
    cout << t.search("ap") << "\n";
    cout << t.search("apply") << "\n";
}

