class Optional {
    bool _has;
    T _val;
public:
    Optional() : _has(false), _val(T{}) {}
    Optional(T val) : _has(true), _val(val) {}
    bool has_value() const { return _has; }
    T value_or(T def) const { return _has ? _val : def; }
    template<typename F>
    auto map(F fn) -> Optional<decltype(fn(_val))> {
        if (_has) return Optional<decltype(fn(_val))>(fn(_val));
        return Optional<decltype(fn(_val))>();
    }
    friend ostream& operator<<(ostream& os, const Optional& o) {
        return o._has ? os << "Some(" << o._val << ")" : os << "None";
    }
};

int main() {
