struct Edge { int to, weight; };

vector<int> dijkstra(int n, int src, const vector<vector<Edge>>& graph) {
    vector<int> dist(n, INT_MAX);
    priority_queue<pair<int,int>, vector<pair<int,int>>, greater<>> pq;
    dist[src] = 0;
    pq.push({0, src});
    while (!pq.empty()) {
        auto [d, u] = pq.top(); pq.pop();
        if (d > dist[u]) continue;
        for (auto& [v, w] : graph[u])
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                pq.push({dist[v], v});
            }
    }
    return dist;
}

int main() {
    int n = 4;
    vector<vector<Edge>> g(n);
    g[0].push_back({1, 1});
    g[0].push_back({2, 4});
    g[1].push_back({2, 2});
    g[1].push_back({3, 5});
    g[2].push_back({3, 1});
    auto dist = dijkstra(n, 0, g);
    for (int i = 0; i < n; i++)
        cout << "dist[" << i << "] = " << dist[i] << "\n";
}

