template<typename T>
class Observable {
    T _value;
    vector<function<void(T)>> _observers;
public:
    Observable(T init) : _value(init) {}
    void set(T val) {
        _value = val;
        for (auto& fn : _observers) fn(val);
    }
    T get() const { return _value; }
    void subscribe(function<void(T)> fn) {
        _observers.push_back(fn);
        fn(_value);
    }
};

