using namespace std;

class ThreadPool {
    vector<thread> workers;
    queue<function<void()>> tasks;
    mutex mtx;
    condition_variable cv;
    bool stop = false;
public:
    ThreadPool(size_t n) {
        for (size_t i = 0; i < n; i++)
            workers.emplace_back([this] {
                while (true) {
                    function<void()> task;
                    { unique_lock lock(mtx); cv.wait(lock, [this]{ return stop || !tasks.empty(); }); if (stop && tasks.empty()) return; task = move(tasks.front()); tasks.pop(); }
                    task();
                }
            });
    }
    void enqueue(function<void()> task) {
        { lock_guard lock(mtx); tasks.push(move(task)); }
        cv.notify_one();
    }
    ~ThreadPool() {
        { lock_guard lock(mtx); stop = true; }
        cv.notify_all();
        for (auto& w : workers) w.join();
    }
};

