class DependencyContainer {
    unordered_map<string, any> factories;
    unordered_map<string, any> singletons;
public:
    template<typename T>
    void bind(const string& name, function<T()> factory) {
        factories[name] = factory;
    }
    template<typename T>
    T resolve(const string& name) {
        if (singletons.count(name)) return any_cast<T>(singletons[name]);
        auto factory = any_cast<function<T()>>(factories.at(name));
        T instance = factory();
        singletons[name] = instance;
        return instance;
    }
};

int main() {
    DependencyContainer c;
    c.bind<string>("greeting", []{ return string("Hello, World!"); });
    cout << c.resolve<string>("greeting") << "\n";
}

