vector<vector<int>> combinations(vector<int>& nums, int target) {
    vector<vector<int>> result;
    vector<int> current;
    sort(nums.begin(), nums.end());

    function<void(int, int)> backtrack = [&](int start, int remaining) {
        if (remaining == 0) { result.push_back(current); return; }
        for (int i = start; i < (int)nums.size() && nums[i] <= remaining; i++) {
            if (i > start && nums[i] == nums[i-1]) continue;
            current.push_back(nums[i]);
            backtrack(i + 1, remaining - nums[i]);
            current.pop_back();
        }
    };

    backtrack(0, target);
    return result;
}

