template<typename T>
class SegmentTree {
    int n;
    vector<T> tree;
    function<T(T,T)> combine;
    T identity;
public:
    SegmentTree(const vector<T>& arr, function<T(T,T)> fn, T id)
        : n(arr.size()), tree(4*arr.size()), combine(fn), identity(id) {
        build(arr, 1, 0, n-1);
    }
    void build(const vector<T>& arr, int node, int lo, int hi) {
        if (lo == hi) { tree[node] = arr[lo]; return; }
        int mid = lo + (hi-lo)/2;
        build(arr, 2*node, lo, mid);
        build(arr, 2*node+1, mid+1, hi);
        tree[node] = combine(tree[2*node], tree[2*node+1]);
    }
    T query(int l, int r) { return query(1, 0, n-1, l, r); }
    T query(int node, int lo, int hi, int l, int r) {
        if (r < lo || hi < l) return identity;
        if (l <= lo && hi <= r) return tree[node];
        int mid = lo + (hi-lo)/2;
        return combine(query(2*node, lo, mid, l, r), query(2*node+1, mid+1, hi, l, r));
    }
};

int main() {
