template<typename T>
class lock_free_stack {
    struct node { T data; node* next; };
    atomic<node*> head{nullptr};
public:
    void push(T val) {
        node* n = new node{move(val), head.load()};
        while (!head.compare_exchange_weak(n->next, n));
    }
    optional<T> pop() {
        node* old = head.load();
        while (old && !head.compare_exchange_weak(old, old->next));
        if (!old) return nullopt;
        T val = move(old->data);
        delete old;
        return val;
    }
};

