template<typename T>
class Observable {
    T _value;
    vector<function<void(const T&, const T&)>> _observers;
public:
    Observable(T init) : _value(move(init)) {}
    void set(T newVal) {
        T old = move(_value);
        _value = move(newVal);
        for (auto& fn : _observers) fn(old, _value);
    }
    const T& get() const { return _value; }
    [[nodiscard]] auto watch(function<void(const T&, const T&)> fn) {
        _observers.push_back(fn);
        size_t idx = _observers.size() - 1;
        return [this, idx]{ _observers.erase(_observers.begin() + idx); };
    }
};

int main() {
