class Signal {
    struct Connection {
        int id;
        function<void()> fn;
    };
    vector<Connection> _connections;
    int _nextId = 0;

public:
    int connect(function<void()> fn) {
        int id = _nextId++;
        _connections.push_back({id, move(fn)});
        return id;
    }

    void disconnect(int id) {
        _connections.erase(
            remove_if(_connections.begin(), _connections.end(),
                [id](const Connection& c){ return c.id == id; }),
            _connections.end()
        );
    }

    void emit() {
        for (auto& c : _connections) c.fn();
    }

    size_t count() const { return _connections.size(); }
};

template<typename T>
class Property {
    T _value;
    Signal _changed;
public:
    Property(T init) : _value(move(init)) {}
    const T& get() const { return _value; }
    void set(T val) {
        if (val != _value) {
            _value = move(val);
            _changed.emit();
        }
    }
    int on_change(function<void()> fn) { return _changed.connect(move(fn)); }
    void disconnect(int id) { _changed.disconnect(id); }
    operator const T&() const { return _value; }
    Property& operator=(T val) { set(move(val)); return *this; }
};

int main() {
    Property<int> count(0);
    auto id = count.on_change([&]{ cout << "Count changed to: " << count.get() << "\n"; });
    count = 1;
    count = 2;
    count.disconnect(id);
    count = 99;
    cout << "Final: " << count.get() << "\n";
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <numeric>
using namespace std;

template<typename T>
class PersistentSegTree {
    struct Node { T val; int left, right; };
    vector<Node> nodes;
    int n;
    function<T(T,T)> combine;
    T identity;

    int build(int lo, int hi, const vector<T>& arr) {
        int idx = nodes.size();
        nodes.push_back({identity, -1, -1});
        if (lo == hi) { nodes[idx].val = arr[lo]; return idx; }
        int mid = lo + (hi - lo) / 2;
        nodes[idx].left = build(lo, mid, arr);
        nodes[idx].right = build(mid + 1, hi, arr);
        nodes[idx].val = combine(nodes[nodes[idx].left].val, nodes[nodes[idx].right].val);
        return idx;
    }

    int update(int prev, int lo, int hi, int pos, T val) {
        int idx = nodes.size();
        nodes.push_back(nodes[prev]);
        if (lo == hi) { nodes[idx].val = val; return idx; }
        int mid = lo + (hi - lo) / 2;
        if (pos <= mid) nodes[idx].left = update(nodes[prev].left, lo, mid, pos, val);
        else            nodes[idx].right = update(nodes[prev].right, mid+1, hi, pos, val);
        nodes[idx].val = combine(nodes[nodes[idx].left].val, nodes[nodes[idx].right].val);
        return idx;
    }

    T query(int node, int lo, int hi, int l, int r) {
        if (r < lo || hi < l) return identity;
        if (l <= lo && hi <= r) return nodes[node].val;
        int mid = lo + (hi - lo) / 2;
        return combine(query(nodes[node].left, lo, mid, l, r), query(nodes[node].right, mid+1, hi, l, r));
    }

    vector<int> roots;
public:
    PersistentSegTree(const vector<T>& arr, function<T(T,T)> fn, T id)
        : n(arr.size()), combine(fn), identity(id) {
        nodes.reserve(arr.size() * 40);
        roots.push_back(build(0, n - 1, arr));
    }

    void update(int pos, T val) {
        roots.push_back(update(roots.back(), 0, n-1, pos, val));
    }

    T query(int version, int l, int r) {
        return query(roots[version], 0, n-1, l, r);
    }

    int versions() const { return roots.size(); }
};

int main() {
    vector<int> a = {1, 3, 5, 7, 9};
    PersistentSegTree<int> pst(a, plus<int>(), 0);
    cout << pst.query(0, 1, 3) << "\n"; // 3+5+7=15
    pst.update(2, 10);
    cout << pst.query(0, 1, 3) << "\n"; // still 15
    cout << pst.query(1, 1, 3) << "\n"; // 3+10+7=20
}
